    it('should reject when entityId is empty', async () => {
      await expect(
        service.log({ ...validDto, entityId: '' })
      ).rejects.toThrow(ValidationError);
      await expect(
        service.log({ ...validDto, entityId: '  ' })
      ).rejects.toThrow(ValidationError);
