    it('should reject when performedBy is empty', async () => {
      await expect(
        service.log({ ...validDto, performedBy: '' })
      ).rejects.toThrow(ValidationError);
      await expect(
        service.log({ ...validDto, performedBy: '  ' })
      ).rejects.toThrow(ValidationError);
    });

    it('should accept all valid AuditAction values', async () => {
