      repo.create.mockResolvedValue(created);

      for (const action of Object.values(AuditAction)) {
        await service.log({ ...validDto, action });
        expect(repo.create).toHaveBeenCalledWith(
          expect.objectContaining({ action })
        );
      }
    });
  });

